    id: "AC1110861",
    text: "Acerca da Lei n.º 11.340/2006 (Lei Maria da Penha), julgue\nos itens de 106 a 110.\nA violência psicológica é uma forma de violência\ndoméstica e familiar contra a mulher, entendida como\nqualquer conduta que lhe cause dano emocional e\ndiminuição da autoestima ou que lhe prejudique e\nperturbe o pleno desenvolvimento ou que vise a degradar\nou controlar suas ações, seus comportamentos, suas\ncrenças e suas decisões, mediante qualquer meio que lhe\ncause prejuízo à saúde psicológica e à autodeterminação.",
