    id: "AC985142",
    text: "A trajetória histórica dos movimentos sociais e das lutas\npara a garantia de direitos de crianças, adolescentes,\nmulheres e idosos permitiu a criação de leis para esses\npúblicos: o Estatuto da Criança e do Adolescente (ECA); o\nEstatuto do Idoso; e a Lei n.º 11.340/2006, conhecida como\nLei Maria da Penha. Com base nessas legislações, julgue os\nitens de 67 a 73 .\nPara efeito da Lei Maria da Penha, considera ‐ se como\nviolência doméstica e familiar contra a mulher qualquer\nação ou omissão que cause morte, lesão, sofrimento físico,\nsexual ou psicológico à mulher.",
