    text: "Área: Agente Social / Questão: 11\nNo que se refere à Região Integrada de Desenvolvimento\ndo Distrito Federal e Entorno (RIDE), julgue os itens a\nseguir.\nI A RIDE é composta exclusivamente pelo DF e por\nmunicípios do estado de Goiás.\nII São considerados de interesse da RIDE os serviços\npúblicos comuns ao DF e aos municípios que a integram,\nressalvados aqueles relacionados às áreas de\ninfraestrutura e de geração de empregos.\nIII Município eventualmente criado a partir do\ndesmembramento de território de município que\ncompõe a RIDE passará a compor, automaticamente, a\nreferida região integrada.\nAssinale a opção correta.",
