    id: "AC4455363",
    text: "19\nJulgue os itens a seguir, com base no II Plano Distrital\nde Políticas para as Mulheres (II PDPM).\nA organização política e administrativa do Distrito Federal\npossui contornos próprios definidos pela Constituição\nFederal de 1988 e pela sua Lei Orgânica. Sobre o tema,\njulgue o item a seguir.\nDiferente dos estados membros, o Distrito Federal não\npode ser dividido em municípios, sendo sua base\nterritorial organizada em Regiões Administrativas, cujos\nadministradores regionais são escolhidos\nobrigatoriamente por meio de eleição direta e universal\npelos moradores de cada respectiva região.",
