    text: "No que diz respeito à realidade cultural e ao patrimônio\nhistórico do Distrito Federal e da Região Integrada de\nDesenvolvimento do Distrito Federal e Entorno (RIDE),\njulgue o item a seguir:\nO Distrito Federal detém o título de Patrimônio Cultural\nda Humanidade, concedido pela UNESCO em 1987, que\nabrange a totalidade do seu território administrativo,\nincluindo as áreas rurais e as cidades que surgiram antes\nda construção de Brasília, como Planaltina e Brazlândia,\nvisando a preservação da arquitetura modernista e do\necossistema do Cerrado.",
