    text: "No que se refere à organização administrativa e às\ncompetências legais da Região Integrada de\nDesenvolvimento do Distrito Federal e Entorno (RIDE),\njulgue o item a seguir:\nA coordenação das atividades da RIDE compete ao\nConselho Administrativo da Região Integrada de\nDesenvolvimento do Distrito Federal e Entorno\n(COARIDE), órgão colegiado que conta com a\nparticipação de representantes da União, do Distrito\nFederal, dos estados de Goiás e Minas Gerais, além de\nrepresentantes dos municípios que integram a região.",
