    id: "AC4118085",
    text: "Informática Rede de Computadores / Questão: 43\nEm relação ao Distrito Federal e considerando os aspectos\nsocioeconômicos, demográficos, histórico-culturais e\ngeográfico-ambientais, julgue os itens a seguir.\nO Distrito Federal apresenta o maior produto interno\nbruto (PIB) per capita do Brasil — mais do que o dobro da\nmédia nacional -, porém convive com intensa\ndesigualdade interna, possuindo um dos maiores índices\nde Gini entre as unidades federativas.",
