    id: "AC4118659",
    text: "A respeito do Distrito Federal e considerando-se os\naspectos socioeconômicos, demográficos, histórico-\nculturais e geográfico-ambientais, julgue os itens a seguir.\nDe acordo com o Instituto Brasileiro de Geografia e\nEstatística (IBGE), a generalidade do território do Distrito\nFederal está inserida no bioma Cerrado, sendo as áreas\nremanescentes ocupadas por porções fragmentadas de\noutros biomas.",
