    id: "AC4118089",
    text: "não definido / Questão: 52\nEm relação ao Distrito Federal e considerando os aspectos\nsocioeconômicos, demográficos, histórico-culturais e\ngeográfico-ambientais, julgue os itens a seguir.\nO Festival de Brasília do Cinema Brasileiro, criado em 1960,\nno ano de inauguração da capital federal, consolidou-se\ncomo um marco cultural da capital federal — é o festival\nde cinema mais antigo do País e simboliza a relevância de\nBrasília no cenário audiovisual nacional, com a sua\npremiação Troféu Candango.",
