    id: "AC4081488",
    text: "A ocupação e a organização territorial do Distrito\nFederal e de seu Entorno (RIDE) são processos\ndinâmicos, marcados por uma contínua evolução\nhistórica, demográfica e administrativa. Desde os núcleos\nurbanos preexistentes à construção da capital, como\nPlanaltina, até a criação de novas Regiões\nAdministrativas para atender às demandas de uma\npopulação em constante crescimento, a configuração\nespacial da região reflete complexas interações sociais e\npolíticas. Dados recentes do Censo Demográfico revelam\num crescimento populacional acentuado nos municípios\nda Periferia Metropolitana de Brasília (PMB), muitas vezes\nsuperando o ritmo da capital, o que impõe desafios para\no planejamento integrado e a gestão de políticas\npúblicas.\nTendo o texto acima como referência inicial e\nconsiderando os múltiplos aspectos da realidade étnica,\nsocial, histórica, geográfica e administrativa do Distrito\nFederal e da RIDE, julgue os itens a seguir.\nA Área Metropolitana de Brasília (AMB) e a Região\nIntegrada de Desenvolvimento do Distrito Federal e\nEntorno (RIDE-DF) são termos que se referem ao mesmo\nrecorte territorial, sendo a AMB a denominação técnica\nutilizada pela Codeplan/IPEDF para fins de pesquisa.",
