    id: "AC4143827",
    text: "não definido / Questão: 51\nRaimunda mora em Águas Lindas (GO) e trabalha como\ntécnica de enfermagem em Samambaia (DF). No\nconselho escolar do filho, ela relata filas na UPA do\nEntorno, ônibus intermunicipais lotados e dificuldades\nem reconhecer consultas marcadas no DF para\nmoradores de cidades goianas vizinhas. A comunidade\ndecide pressionar por uma solução jurídico-institucional\nque integre planejamento, investimentos e serviços\npúblicos que transbordam as fronteiras do DF, de Goiás e\naté de Minas Gerais. Considerando as competências e\ninstrumentos existentes, assinale a alternativa que\ndescreve corretamente o arranjo e sua governança que\npermitem pactuações interfederativas para funções\npúblicas de interesse comum nessa área.",
