    text: "não definido / Questão: 53\nA realidade do Distrito Federal é marcada por uma rica\ncomplexidade histórica, social e política. Um dos\nelementos cruciais para a gestão e desenvolvimento da\nregião é a Região Integrada de Desenvolvimento do\nDistrito Federal e Entorno (RIDE).Instituída pela Lei\nComplementar n. 94/1998.\nCom base no trecho acima, julgue os itens a seguir\nA construção de Brasília promoveu um intenso fluxo\nmigratório para o Planalto Central, atraindo trabalhadores\nde diversas regiões do Brasil, especialmente do Nordeste.\nEsses migrantes, conhecidos como “candangos”, foram\nfundamentais para a edificação da nova capital e\ncontribuíram significativamente para a formação da\ndiversidade étnica e cultural do Distrito Federal.",
