    text: "No Atendimento Pré-Hospitalar (APH), a escolha da\ntécnica adequada para o manejo de sangramentos é\ncondicionada pela gravidade, localização e profundidade\nda lesão. Considerando os protocolos de controle de\nhemorragias e as diretrizes assistenciais para o uso de\nmétodos mecânicos e farmacológicos, assinale a\nalternativa correta.",
