    id: "AC4386126",
    text: "Assistente Social / Questão: 28\nA necessária colisão de valores e de princípios, inerentes ao\ndesenvolvimento de uma sociedade, mostra que o\njulgamento adequado da correção de uma conduta é uma\natividade complexa para todos os que lidam com a\natividade administrativa. As regras deontológicas de\natuação profissional e os princípios que regem a atuação\ndos agentes públicos, expressos na Constituição Federal\nde 1988, lançam as luzes para o desenvolvimento de\ninstitutos e para a decisão correta acerca do\ncomportamento de elevada probidade e largo\ncompromisso ético. A partir dessa informação, julgue os\nitens a seguir\nCausar espera injustificada na prestação de serviços\npúblicos viola a ética pública e produz grave dano moral\naos usuários dos serviços públicos.",
