    id: "AC1509636",
    text: "João da Borda é servidor público e, na repartição em que\ntrabalha, é responsável pelo atendimento ao público. São\ndeveres fundamentais de João da Borda, nos exatos\ntermos do Código de Ética Profissional do Servidor Público\nCivil do Poder Executivo Federal, o Decreto Federal nº\n1.171/94:\nI. Jamais retardar qualquer prestação de contas, condição\nessencial da gestão dos bens, direitos e serviços da\ncoletividade a seu cargo.\nII. Comunicar imediatamente a seus superiores ato ou fato\nque julgar em sua consciência contrário ao interesse\npúblico, exigindo as providências cabíveis.\nIII. Facilitar a fiscalização de todos os atos ou serviços por\nquem de direito, exceto nos casos em que haja\ndeterminação superior em contrário.\nIV. Ter respeito à hierarquia, porém sem nenhum temor de\nrepresentar contra qualquer comprometimento indevido\nda estrutura em que se funda o Poder Estatal, salvo se se\ntratar de seu subordinado, caso em que poderá exercer a\naplicação de penalidades sensíveis ao cargo que ocupa.\nV. Ser cortês, ter urbanidade, sensibilidade e atenção,\nrespeitando a capacidade e as restrições pessoais de todos\nos usuários do serviço público, sem preconceito ou\ndistinção de raça, gênero, estereótipos e religião.\nAssinale a alternativa correta:",
