    id: "AC4516906",
    text: "Estadual - Administração / Questão: 58\nO controle da Administração Pública compreende os\nmecanismos jurídicos e institucionais destinados a\nverificar a conformidade dos atos administrativos com o\nordenamento jurídico e a promover a responsabilização\ndos agentes. Acerca do assunto, registre V, para as\nafirmativas verdadeiras, e F, para as falsas:\n( )O controle da Administração Pública pode ser\nclassificado quanto ao órgão que o exerce (controle\ninterno e controle externo), quanto ao momento de sua\nrealização (controle prévio, concomitante e subsequente)\ne quanto ao aspecto controlado (controle de legalidade,\nde mérito e de resultados).\n( )O controle de mérito dos atos administrativos\ndiscricionários pode ser exercido pelo Poder Judiciário\nsempre que verificar que a decisão administrativa,\nembora formalmente legal, foi inconveniente ou\ninoportunamente tomada, cabendo ao Juízo substituir o\nato pela decisão que reputar mais adequada ao interesse\npúblico.\n( )O controle interno da Administração Pública\ncompreende tanto o controle hierárquico, exercido pelos\nórgãos superiores sobre os inferiores na estrutura\nadministrativa, quanto o controle finalístico, exercido pela\nAdministração Direta sobre as entidades da\nAdministração Indireta a ela vinculadas.\n( )O controle popular, exercido diretamente pelos\ncidadãos e pela sociedade civil, constitui espécie de\ncontrole externo em sentido amplo, materializado em\ninstrumentos como o direito de petição, a ação popular e\nos mecanismos de participação social previstos na Lei\nComplementar Federal nº 101/2000.\nApós análise, assinale a alternativa que apresenta a\nsequência CORRETA dos itens acima, de cima para baixo:",
