    id: "AC3971991",
    text: "Instruções da Banca Examinadora:\nA Prova Discursiva será avaliada considerando-se os\naspectos presentes em Edital:\n1. Conhecimento técnico sobre a matéria.\n2. Utilização adequada da Língua Portuguesa.\nO(A) candidato(a) disporá de, no mínimo, 10 (dez) linhas,\ne, no máximo, 30 (trinta) linhas para elaborar a resposta\nda Prova Discursiva. Será desconsiderado, para efeito de\navaliação, qualquer fragmento de texto que for escrito fora\ndo local apropriado ou que ultrapassar a extensão máxima\npermitida para elaboração.\nNa Prova Discursiva, deverão ser rigorosamente\nobservados os limites mínimos e máximos de linhas\nprevistos, sob pena de perda de pontos a serem atribuídos\nà prova.\nA Prova Discursiva deverá ser feita à mão pelo(a) próprio(a)\ncandidato(a), em letra legível, com caneta esferográfica\ntransparente de tinta azul ou preta, não sendo permitida a\ninterferência e/ou a participação de outras pessoas, salvo\nem caso de candidato(a) a quem tenha sido deferido\natendimento especial para a realização das provas.\nA Versão Definitiva da Prova Discursiva não deve ser\nassinada, rubricada ou conter, em outro local que não o\napropriado, qualquer palavra ou marca que possibilite a\nidentificação do(a) candidato(a).\nO(A) candidato(a) não poderá manusear e consultar\nnenhum tipo de material, devendo atentar-se apenas para\nas informações contidas na Prova Discursiva para sua\nrealização.\nA Folha de Versão Definitiva será o único documento\nválido para a avaliação da Prova Discursiva. A folha para\nrascunho, no caderno de questões, é de preenchimento\nfacultativo e não valerá para a finalidade de avaliação da\nProva Discursiva.\nO(A) candidato(a) terá sua Prova Discursiva avaliada\ncom nota 0 (zero) e estará automaticamente\neliminado(a) do concurso público se:",
