    id: "AC3477769",
    text: "Para o Senado, portanto, a atividade de monitorar os\nresultados e os processos das políticas públicas deve ser\nrealizado sob dois pontos de vista:\n(i) trazer ao conhecimento público e proporcionar o\ndebate sobre a atuação governamental em benefício da\nsociedade e (ii) propor ajustes e aprimoramentos nas\npolíticas públicas, quando necessários e oportunos.\nPara o cumprimento dessa função, as equipes de\nassessoramento envolvidas na avaliação de políticas\npúblicas no Senado poderão trabalhar em dois níveis.\n(...)\nNo segundo nível, complementar ao primeiro, as equipes\nde assessoramento analisam e consolidam informações\nconstantes de estudos e avaliações previamente\nrealizados por outras instituições, tais como relatórios\nproduzidos por universidades, centros de pesquisa e\ninstituições privadas, pelos próprios órgãos responsáveis\npela execução da política avaliada, por organizações\ninternacionais e, especialmente, os relatórios de auditorias\nanteriormente realizadas pelo TCU.\n(BRASIL, Senado Federal. Referencial de Avaliação de\nPolíticas Públicas do Senado Federal. Brasília, 2015, p.3-6)\nA abordagem do segundo nível assume contornos muito\npróximos aos atribuídos pela técnica da meta-avaliação, a\nqual, resumidamente, é uma avaliação da avaliação. As\nmeta-avaliações possuem três características principais.\nSobre as características da meta-avaliação, analise as\nafirmativas a seguir.\nI. São sínteses de achados sobre avaliação de programas e\ninferências sobre o desempenho do programa, a partir\ndos resultados encontrados.\nII. Informam sobre a validade e a utilidade dos métodos\nde avaliação e oferecem direção sobre sua utilidade de\navaliar.\nIII. Fornecem forte evidência do impacto do programa,\nsubsidiando a tomada de decisão.\nEstá correto o que se afirma em",
