    id: "AC285463",
    text: "Área Psicologia / Questão: 106\nEste estudo descreve como se estruturam as redes\ninformais dos empresários participantes das incubadoras\nde empresas de base tecnológica do Recife. Trata-se de\num estudo de caso, com uma amostra que reúne mais de\n60% dos empresários das sete incubadoras de base\ntecnológica do Recife. Fez-se um corte epistemológico ao\nlimitar o estudo aos padrões de rede caracterizados por\nconteúdos específicos nela transacionados, a saber: as\nredes de amizade, de informação e de confiança. Para o\nmapeamento das redes, foi utilizado o software UCINET 6.\nIdentificou-se que a rede de confiança é maior do que a\nrede de informação e que laços fortes de interação\npredominam no ambiente das incubadoras. Essas\ncaracterísticas não favorecem os processos de inovação,\numa vez que as redes de laços fortes frequentemente se\nfecham à entrada de informações novas. Os achados\ntambém mostraram que a construção da rede dos\nempresários incubados é baseada na diversidade de\npapéis.\nConsiderando a descrição acima, julgue os itens seguintes\nquanto a métodos e técnicas em pesquisa organizacional.\nO estudo tem caráter explicativo.",
