    id: "AC3075093",
    text: "Considere a situação hipotética a seguir.\nLuís cometeu, em 10/10/2022, o fato descrito no artigo 33,\ncaput da Lei nº 11.343/06. Em razão desse fato, foi\ncondenado a uma pena privativa de liberdade (PPL) de\ncinco anos e dez meses de reclusão em regime\nsemiaberto e 500 dias-multa. A condenação transitou em\njulgado em 22/09/2023. A guia de execução definitiva\n(guia nº 1) foi expedida em 25/09/2023, data em que\nigualmente se autuou o processo de execução e se\nexpediu mandado de prisão para cumprimento da pena.\nO sentenciado foi preso em 26/09/2023, dando-se início à\nexecução em regime semiaberto.\nEm novembro de 2023, no curso do cumprimento da\npena da guia nº 1, sobreveio nova condenação a três anos\nde detenção e 20 dias-multa por ter praticado, em\n15/12/2022, o crime disposto no artigo 12 da Lei nº\n10.826/03. Na sentença, o juízo da condenação fixou o\nregime aberto e substituiu a pena privativa de liberdade\npor duas penas restritivas de direitos (PRDs), consistentes\nem prestação de serviços à comunidade e limitação de\nfim de semana. A condenação transitou em julgado em\n20/11/2023. A guia de execução definitiva (guia nº 2) foi\nexpedida em 21/11/2023. No dia 23/11/2023, a guia nº 2 foi\njuntada nos autos da execução penal.\nEm consonância com a jurisprudência do Superior\nTribunal de Justiça, diante das duas guias de execução\npresentes nos autos, deverá o juiz da execução penal",
