    id: "AC1547091",
    text: "Acerca da Execução Penal, analise as seguintes assertivas:\nI - São órgãos da execução penal, entre outros, o Juízo da\nExecução, os Departamentos Penitenciários, o Conselho\nda Cidade e o Patronato.\nlI - Segundo jurisprudência do STJ, o tempo de duração\nda medida de segurança não deve ultrapassar o limite\nmáximo da pena abstratamente cominada ao delito\npraticado.\nIlI - Conforme jurisprudência do STJ, falta grave\ninterrompe a contagem do prazo para a progressão de\nregime de cumprimento de pena e comutação de pena,\nporém não interrompe para o indulto.\nIV - De acordo com entendimento sumular do STF, a falta\nde estabelecimento penal adequado autoriza a\nmanutenção do condenado em regime prisional mais\ngravoso.\nV - Ainda conforme entendimento sumular do STF,\nadmite-se a progressão de regime ou a aplicação\nimediata de regime menos severo nela determinada,\nantes do trânsito em julgado da sentença condenatória.\nEstá CORRETO o que se afirma em:",
