    text: "Em relação ao direito do condenado ao trabalho externo é\ncorreto afirmar:\nI. O trabalho externo será admissível para os presos em\nregime fechado somente em serviço ou obras públicas\nrealizadas por órgãos da Administração Direta ou Indireta,\nou entidades privadas, desde que tomadas as cautelas\ncontra a fuga e em favor da disciplina.\nII. O limite máximo do número de presos será de 20%\n(vinte por cento) do total de empregados na obra.\nIII. A prestação de trabalho à entidade privada depende\ndo consentimento expresso do preso.\nIV. A prestação de trabalho externo, a ser autorizada pela\ndireção do estabelecimento, dependerá de aptidão,\ndisciplina e responsabilidade, além do cumprimento\nmínimo de 1/4 (um quarto) da pena.\nA sequência correta é:",
