    id: "AC781793",
    text: "Questão: 85\nCom relação a assistência educacional e a assistência do\ntrabalho do preso, fatores fundamentais para o reingresso do\napenado na sociedade, julgue os itens seguintes. SITUAÇÃO\nHIPOTÉTICA: João, em cumprimento de pena em regime\nfechado, ao executar serviço de limpeza dentro do\nestabelecimento prisional, acidentou-se gravemente, o que\nresultou na perda de um dos dedos de sua mão direita.\nASSERTIVA: Nessa situação, e considerando-se o fato de que o\ntrabalho interno é remunerado, João tem direito a indenização\ncom base nas disposições legais trabalhistas.",
