    text: "Assistente Técnico Administrativo - Área: Informática / Questão: 19\nAcerca dos órgão da execução penal, analise as assertivas,\na seguir.\nl. O Conselho Nacional de Política Criminal e Penitenciária\nserá integrado por onze membros designados através de\nato do Ministério da Justiça, dentre professores e\nprofissionais da área do Direito Penal, Processual Penal,\nPenitenciário e ciências correlatas, bem como por\nrepresentantes da comunidade e dos Ministérios da área\nsocial.\nll. O Conselho Penitenciário é órgão consultivo e\nfiscalizador da execução da pena, enquanto que o\nPatronato público ou particular destina-se a prestar\nassistência aos albergados e aos egressos.\nIll. O Departamento Penitenciário Nacional, subordinado\nao Ministério da Justiça, é órgão executivo da Política\nPenitenciária Nacional e de apoio administrativo e\nfinanceiro do Conselho Nacional de Política Criminal e\nPenitenciária.\nIV. Haverá, em cada comarca, pelo menos dois Conselhos\nda Comunidade compostos, no mínimo, por um\nrepresentante de associação comercial ou industrial, um\nadvogado indicado pela Seção da Ordem dos Advogados\ndo Brasil, um Defensor Público indicado pelo Defensor\nPúblico Geral, um Promotor de Justiça indicado pelo\nProcurador Geral de Justiça e um assistente social\nescolhido pela Delegacia Seccional do Conselho Nacional\nde Assistentes Sociais.\nEstá correto, apenas, o que se afirma em:",
