    id: "AC867229",
    text: "Em cada um dos itens seguintes, é apresentada uma situação\nhipotética, seguida de uma assertiva a ser julgada com base\nna Lei de Execuções Penais. Geraldo foi condenado,\ndefinitivamente, pela prática de crime de roubo, a cinco anos e\nquatro meses de reclusão, em regime semi-aberto, e a 120\ndias-multa. Após o cumprimento de um sexto da pena, e\ndevido ao comportamento adequado, Geraldo obteve\nautorização judicial para freqüentar curso supletivo\nprofissionalizante. No entanto, alguns dias depois, o promotor\ndenunciou-o por crime de estupro contra Laís, que teria sido\npraticado em uma de suas saídas. Até esse momento, a única\nprova contra Geraldo era a palavra da vítima. Nessa situação,\nsomente após decisão condenatória definitiva pela prática de\nestupro, Geraldo perderia o benefício da saída temporária,\ndevido ao princípio da presunção de não-culpabilidade.",
