    text: "Uma gestão da segurança e saúde bem planejada,\nimplementada e avaliada pode evitar acidentes no\ntrabalho. Medidas técnicas de prevenção, administrativas\ne pessoais devem ser levadas a sério, assim como o\ntreinamento para espaço confinado e trabalho em altura.\nAcerca da prevenção contra fatores de risco de acidentes\nem espaços confinados e no trabalho em altura, bem\ncomo da segurança no trânsito, julgue os itens a seguir.\nNo trânsito, para o condutor guardar uma distância\nfrontal segura entre seu veículo e os demais, ele deve\nconsiderar a velocidade e as condições climáticas do local\ne do veículo.",
