    id: "AC3513760",
    text: "O texto seguinte servirá de base para responder às questões de 46 a 50.\nA segurança no transporte de passageiros é uma prioridade nas políticas de\ntrânsito e nas práticas de condução veicular. Envolve não apenas o respeito às\nnormas e regulamentações, mas também a adoção de atitudes preventivas\nque visam proteger todos os ocupantes do veículo, especialmente os mais\nvulneráveis, como crianças, idosos e pessoas com necessidades especiais. O\nuso correto dos equipamentos de segurança, a manutenção adequada do\nveículo e a conscientização dos passageiros sobre seu papel na segurança\ncoletiva são elementos fundamentais para evitar acidentes e garantir um\ntransporte seguro.\nConsiderando o contexto apresentado, julgue os itens a seguir:\nA manutenção preventiva do veículo, como verificação de\nfreios, pneus e sistemas de iluminação, é uma prática\nrecomendada, mas não obrigatória, para veículos de\ntransporte de passageiros.",
