    id: "AC3412850",
    text: "No período de 2012 a 2022, foram notificados no Brasil\n1.237.027 casos de sífilis adquirida, 537.401 casos de sífilis em\ngestantes, 238.387 casos de sífilis congênita e 2.153 óbitos\npor sífilis congênita. Destaca-se que o Sistema Único de\nSaúde (SUS) possui testes não treponêmicos e testes\ntreponêmicos para sífilis incorporados na sua lista de\nprocedimentos, e que o Ministério da Saúde adquire e\nfornece testes rápidos para sífilis aos serviços de saúde.\nDiante do exposto, assinale a alternativa que contém apenas\ntestes não treponêmicos.",
