    text: "A terapia fonoaudiológica desempenha um papel crucial na\nrecuperação da funcionalidade e no alívio dos sintomas\nassociados à disfunção da articulação temporomandibular\n(DTM). Sobre o assunto, avalie as proposições:\nI.A reabilitação da DTM deve considerar não apenas os\nsintomas físicos, como dor e restrição de movimento, mas\ntambém a necessidade de uma abordagem interdisciplinar\nque envolva terapia fonoaudiológica e psicoterapia, devido à\nsua complexidade.\nII.A DTM é relacionada a fatores mecânicos da articulação,\ncomo desarranjos do complexo côndilo/disco, e não\napresenta correlação com aspectos neuromusculares ou\npsicossociais.\nIII.As manifestações clínicas da DTM são restritas à dor na\nregião mandibular, sem impactar outras áreas funcionais,\ncomo a fala e a deglutição, uma vez que a articulação\ntemporomandibular é independente de outras funções\norofaciais.\nAssinale a alternativa correta:",
