    text: "A psiquiatria social é um ramo da psiquiatria que se\nconcentra no estudo das interações entre saúde mental,\nindivíduos e sociedade. Os profissionais de psiquiatria social\nfrequentemente trabalham em equipes multidisciplinares e\ncolaboram com profissionais de diferentes áreas como\npsicologia, serviço social, direito, saúde pública e educação\npara abordar questões relacionadas à saúde mental em um\ncontexto amplo. Assinale a alternativa que melhor descreve\na psiquiatria social enquanto uma disciplina relevante para a\nsaúde pública.",
