    text: "Física / Questão: 6\nO trabalho diário com alunos em movimento faz com que o\nconhecimento sobre primeiros socorros seja essencial para\na atuação do professor de Educação Física na escola.\nMesmo que sua prática pedagógica seja planejada a partir\nde estratégias de prevenção bem definidas, situações\ninesperadas sempre vão existir, podendo colocar a saúde e a\nvida de todos da comunidade escolar em risco. Dessa forma,\nanalise as afirmações a seguir, sobre os procedimentos\ncorretos a serem tomados por este profissional, para\nminimizar situações de risco ou fazer o melhor possível\nquando tiver o dever de prestar socorro:\nI- O professor de Educação Física deve conhecer os riscos\ninerentes a sua atuação profissional no âmbito escolar e\nadotar medidas de prevenção em sua prática pedagógica,\nrecebendo capacitações anuais de primeiros socorros\nprevistas em lei.\nII- O professor de Educação Física deve saber diferenciar um\nacidente de um incidente, não acionando o serviço\nespecializado em atendimento de primeiros socorros neste\núltimo caso, tendo em vista que é um tipo de ocorrência em\nque não há danos à integridade física do indivíduo.\nIII- O professor de Educação Física deve acionar o serviço\nespecializado em atendimento de primeiros socorros\napenas quando houver situações de urgência, tendo em\nvista que, ao contrário das situações de emergência, o que\nestá em risco nestas ocorrências é a vida do indivíduo.\nÉ CORRETO o que se afirma em:",
